  ('female_visibility_hard','pattern','(^|[^a-z])(female (presenter|host|speaker|lecturer|teacher|interviewer|singer|podcaster|influencer|guest)|woman speaker|women speaker|actress|actresses|ustadha|shaykha|sister lecture|sisters only|hijab tutorial|makeup tutorial|miss world|miss universe|beauty pageant|modeling|model runway|fashion show|red carpet)($|[^a-z])','hard','title_description',true,'Female visibility — auto-block per halal policy'),
